#include <stdio.h>
#include <string.h>

void listaDePresenca(void) {
    char lista[4][20] = {"ana", "bia", "caio", "rui"};
    char nome[20] = "";
    int achou = 0;
    scanf("%19s", nome);
    for (int i = 0; i < 4; i++) {
        if (strcmp(nome, lista[i]) == 0) {
            achou = 1;
        }
    }
    if (achou == 1) {
        printf("presente\n");
    } else {
        printf("ausente\n");
    }
}
